def _backfill() -> None:
    """Fill new columns on existing rows and copy JSON skill lists into the normalized tables."""
    import json
    import uuid

    bind = op.get_bind()
    run = lambda sql, **kw: bind.execute(sa.text(sql), kw)  # noqa: E731

    run("UPDATE applications SET organization_id = (SELECT jobs.organization_id FROM jobs WHERE jobs.id = applications.job_id) WHERE organization_id IS NULL")
    run("UPDATE applications SET source = 'applied' WHERE source IS NULL")
    run("""UPDATE candidate_profiles SET source = COALESCE(source, 'self_registered'), availability = COALESCE(availability, 'open'),
           phone = COALESCE(phone, ''), industry = COALESCE(industry, ''),
           preferred_locations_json = COALESCE(preferred_locations_json, '[]'), employment_types_json = COALESCE(employment_types_json, '[]')""")
    run("""UPDATE jobs SET employment_type = COALESCE(employment_type, 'Full-time'), openings = COALESCE(openings, 1),
           seniority = COALESCE(seniority, ''), industry = COALESCE(industry, '')""")
    run("UPDATE jobs SET published_at = created_at WHERE status = 'Active' AND published_at IS NULL")

    skills = {name.lower(): sid for sid, name in bind.execute(sa.text("SELECT id, name FROM skill_taxonomies"))}

    def skill_id(name: str) -> str:
        key = name.strip().lower()
        if key not in skills:
            sid = f"tax_{uuid.uuid4().hex[:8]}"
            run("INSERT INTO skill_taxonomies (id, name, category, demand_level, avg_salary_boost) VALUES (:id, :name, 'Uncategorized', 'Medium', '')",
                id=sid, name=name.strip())
            skills[key] = sid
        return skills[key]

    def names(raw):
        try:
            return [n for n in json.loads(raw or "[]") if isinstance(n, str) and n.strip()]
        except ValueError:
            return []

    for cid, raw in list(bind.execute(sa.text("SELECT id, skills_json FROM candidate_profiles"))):
        seen = set()
        for pos, name in enumerate(names(raw)):
            sid = skill_id(name)
            if sid in seen:
                continue
            seen.add(sid)
            run("INSERT INTO candidate_skills (id, candidate_id, skill_id, proficiency, position) VALUES (:id, :c, :s, '', :p)",
                id=f"cs_{uuid.uuid4().hex[:12]}", c=cid, s=sid, p=pos)

    for jid, req, pref in list(bind.execute(sa.text("SELECT id, required_skills_json, preferred_skills_json FROM jobs"))):
        seen = set()
        for importance, raw in (("required", req), ("preferred", pref)):
            for pos, name in enumerate(names(raw)):
                sid = skill_id(name)
                if sid in seen:
                    continue
                seen.add(sid)
                run("INSERT INTO job_skills (id, job_id, skill_id, importance, position) VALUES (:id, :j, :s, :i, :p)",
                    id=f"js_{uuid.uuid4().hex[:12]}", j=jid, s=sid, i=importance, p=pos)


